import numpy as np
from metpy.units import units

def test_where_scalar():
    mag = np.array([0.0, 1.0]) * units.K / units.m
    res = np.array([np.nan, 1.0]) * units.K / units.m / units.s

    # Try np.where with scalar 0.0
    try:
        out = np.where(mag == 0, 0.0, res)
        print(f"np.where result: {out}")
    except Exception as e:
        print(f"np.where failed: {e}")

if __name__ == "__main__":
    test_where_scalar()

